package br.com.tapeteskalke.dto;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.*; import java.util.List;
public final class OperacaoDtos { private OperacaoDtos(){} public record VendaItem(@NotBlank String produtoId,@NotNull @DecimalMin(value="0.001") BigDecimal quantidade){} public record VendaRequest(@NotBlank String clienteId,String vendedorId,LocalDate dataVenda,@NotNull @DecimalMin("0.00") BigDecimal desconto,@NotBlank String formaPagamento,@NotEmpty List<@Valid VendaItem> itens,String observacoes){} public record VendaResponse(String id,Long numeroVenda,String cliente,LocalDate dataVenda,BigDecimal subtotal,BigDecimal desconto,BigDecimal total,String status,String formaPagamento){} public record CancelarRequest(@NotBlank @Size(max=500) String motivo){}
 public record CompraItem(@NotBlank String produtoId,@NotBlank @Pattern(regexp="COMERCIAL|PRODUCAO") String destinoEstoque,@NotNull @DecimalMin(value="0.001") BigDecimal quantidade,@NotNull @DecimalMin("0.00") BigDecimal precoUnitario){} public record CompraRequest(String fornecedorId,String fornecedorNomeManual,@NotNull LocalDate dataCompra,@NotEmpty List<@Valid CompraItem> itens,String observacoes){} public record CompraResponse(String id,LocalDate dataCompra,String fornecedor,BigDecimal total,String status){}
 public record MateriaPrima(@NotBlank String produtoId,@NotNull @DecimalMin(value="0.001") BigDecimal quantidadeUsada){} public record OrdemRequest(@NotBlank String produtoAcabadoId,@NotNull @DecimalMin(value="0.001") BigDecimal quantidadeProduzida,@NotBlank @Pattern(regexp="ESTOQUE|ENCOMENDA") String tipoOrdem,String clienteId,String fornecedorId,@NotEmpty List<@Valid MateriaPrima> materiasPrimas,String observacoes){} public record OrdemResponse(String id,Long numeroOrdem,String produto,BigDecimal quantidade,String status,LocalDate data,String origem,String observacoes){}
 public record EntregaRequest(@NotBlank String vendaId,String enderecoEntrega,String bairro,String cidade,String cep,String telefoneContato,LocalDate dataAgendada,LocalTime horario,String entregadorId,@DecimalMin("0.00") BigDecimal valorFrete,String observacoes){} public record EntregaStatusRequest(@NotBlank @Pattern(regexp="AGENDADA|EM_ROTA|ENTREGUE|NAO_ENTREGUE") String status){} public record EntregaResponse(String id,String cliente,String vendaId,Long numeroVenda,String entregador,String status,LocalDate dataAgendada,LocalTime horario,OffsetDateTime dataEntrega){}
 // Inventário: contagem física de um saldo; só os itens com diferença geram movimento.
 public record InventarioItem(@NotBlank String produtoId,@NotNull @DecimalMin("0") BigDecimal contado){} public record InventarioRequest(@NotBlank @Pattern(regexp="COMERCIAL|PRODUCAO") String saldo,@Size(max=300) String observacao,@NotEmpty List<@Valid InventarioItem> itens){} public record InventarioDiferenca(String produto,BigDecimal sistema,BigDecimal contado,BigDecimal diferenca){} public record InventarioResumo(int contados,int comDiferenca,List<InventarioDiferenca> diferencas){}
 public record MovimentoResponse(String id,OffsetDateTime data,String produtoId,String produto,String saldo,String tipo,String origem,String idOrigem,BigDecimal quantidade,BigDecimal anterior,BigDecimal posterior,String usuario,String observacao){}
 public record DespesaRequest(@NotBlank @Pattern(regexp="SALARIOS|FRETES|MANUTENCAO|OUTROS") String tipo,@NotBlank @Size(max=255) String descricao,@NotNull @DecimalMin(value="0.01") BigDecimal valor,@NotNull LocalDate dataDespesa,String observacoes){}
}